<!doctype html>
<html>
<head lang="zh">
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1, minimum-scale=1, maximum-scale=1, user-scalable=no">
<meta http-equiv="x-ua-compatible" content="ie=edge">
<link rel="icon" href="yuedu.svg">
<title>写源助手</title>
<style>
body {
  background-color: #f4f5f7;
  display: flex;
  flex-wrap: wrap;
  place-content: center;
  place-items: start;
}
.card {
  border-top: .5px solid rgba(255,255,255,.7);
  color: #001944;
  border-radius: 24px;
  background-color: rgba(255,255,255,.5);
  box-shadow: 0px 10px 20px rgba(0,0,0,.05);
  padding: 30px;
  margin: 12.5px;
  width: 250px;
}
.flex {
  display: flex;
  flex-wrap: wrap;
}
details + div {
  overflow: hidden;
  max-height: 0;
  opacity: 0;
  transition: .5s;
}
[open] + div {
  max-height: 888px;
  opacity: 1;
}
summary {
  font-size: 23px;
  font-weight: 700;
  user-select: none;
  outline: 0;
  opacity: .45;
  transition: .5s;
  display: block;
}
[open] summary {
  opacity: 1;
  margin-bottom: 7px;
  font-size: 20px;
}
a {
  margin-top: 7px;
  display: inline-block;
  span { margin-left: 7px; }
}
span {
  background-color: rgba(0,0,0,.04);
  font-family: monospace;
  font-size: 13px;
  padding: .125em .25em;
  border-radius: .5em;
  opacity: .8;
}
button {
  font-size: 13px;
  font-weight: 700;
  color: #4360b7;
  background-color: #e7eeff;
  padding: 6.5px 13px;
  margin-top: 7px;
  margin-right: 7px;
  border-radius: 28px;
  border:none;
  transition: .3s;
}
button:active { background-color: #d6ddee; }
textarea {
  margin-top: 7px;
  padding: 7px;
  width: 232px;
  min-height: 72px;
  max-height: 143px;
  display: block;
  resize: vertical;
  font-size: 13px;
  border-radius: 8px;
  color: #333;
  border: 2px solid rgba(0,0,0,.1);
  background-color: rgba(0,0,0,.01);
}
#matchText,
#replaceText {
  resize: none;
  min-height: 17px;
  max-height: 17px;
}
input {
  appearance: none;
  vertical-align: middle;
  margin-right: 3px;
  margin-bottom: 6px;
  width: 15px;
  height: 15px;
  background-color: rgba(0,0,0,.01);
  border: 2px solid rgba(0,0,0,.1);
  border-radius: 8px;
  transition: .3s;
}
input:checked { border-color: #4360b7; }
label {
  display: inline-block;
  margin-top: 10px;
  font-size: 15px;
}
#tip { margin-top: 7px; }
#temp { display: none; }
</style>
</head>
<body>
<div class="card">
  <details>
    <summary>发现格式工具</summary>
  </details>
  <div>
    <textarea id="text" placeholder="请输入要处理的内容"></textarea>
    <a>格式转换</a>
    <div class="flex">
      <button onclick="Format()">html转旧发现</button>
      <button onclick="Switch()">新旧发现互转</button>
    </div>
    <a>每行列数<span>仅新发现</span></a>
    <div class="flex">
      <button onclick="Add(1)">1</button>
      <button onclick="Add(0.4)">2</button>
      <button onclick="Add(0.25)">3</button>
      <button onclick="Add(0.2)">4</button>
      <button onclick="Add(0.15)">5</button>
    </div>
    <a>快捷功能</a>
    <div class="flex">
      <button onclick="Copy('#text')">复制全文</button>
      <button onclick="Cut('#text')">剪切全文</button>
      <button onclick="Empty('#text')">清空</button>
    </div>
  </div>
</div>
<div class="card">
  <details>
    <summary>正则匹配替换</summary>
  </details>
  <div>
    <textarea id="text1" placeholder="请输入要处理的内容"></textarea>
    <a>正则匹配</a>
    <textarea id="matchText" placeholder="正则表达式"></textarea>
    <label>
      <input id="global" type="checkbox" checked>
      全局搜索
    </label>
    <label>
      <input id="ignoreCase" type="checkbox">
      忽略大小写
    </label>
