    </div>
  </div>
</div>
<script>
function $(t) {
  return document.querySelector(t);
}
function $$(t) {
  document.execCommand(t);
}
function Format() {
  t = $('#text');
  list = t.value.match(/<[^<]+?href=['"](.*?)['"][^<]*?>(.*?)</g);
  if (list) {
    html = "";
    for (i = 0; i < list.length; i++) {
      a = list[i].match(/<[^<]+?href=['"](.*?)['"][^<]*?>(.*?)</g);
      html += a[2] + "::" + a[1] + "\r\n"
    };
    t.value = html.replace(/\r\n$/, "");
  }
}
function Switch() {
  t = $('#text');
  try {
    html = "";
    json = JSON.parse(t.value);
    for (i = 0; i < json.length; i++) {
      html += json[i].title + "::" + json[i].url + "\r\n"
    };
    t.value = html.replace(/\r\n$/, '');
  } catch(err) {
    if (t.value.match(/\&\&|::/g)) {
      text = t.value.replace(/\&\&/g, '\r\n');
      list = text.match(/.*?::.*/g);
      html = [];
      for (i = 0; i < list.length; i++) {
        a = list[i].match(/(.*?)::(.*)/);
        html.push({
          title: a[1],
          url: a[2],
        });
      };
      t.value = JSON.stringify(html);
    }
  }
}
function Add(t) {
  x = $('#text');
  try {
    json = JSON.parse(x.value);
    for (i = 0; i < json.length; i++) {
      json[i].style = {
        layout_flexGrow: 1,
        layout_flexBasisPercent: t,
      }
    };
    x.value = JSON.stringify(json);
  } catch(err) {
    "";
  }
}
function Copy(t) {
  $(t).select();
  $$('copy');
}
function Cut(t) {
  $(t).select();
  $$('cut');
}
function Empty(t) {
  $(t).value = "";
  $(t).focus();
}
function Reset() {
  $('#text1').value = $('#matchText').value = $('#tip').textContent = $('#matchResult').value = $('#replaceText').value = $('#replaceResult').value = "";
  $('#text1').focus();
}
function BuildRegex() {
  text = $('#text1');
  if (!text.value) {
    text.focus();
    return false;
  }
  match = $('#matchText');
  if (!match.value) {
    match.focus();
    return false;
  }
  op = $('#global').checked ? "g": "";
  op = $('#ignoreCase').checked ? op + "i": op;
  return new RegExp(match.value, op);
}
function Match() {
  regex = BuildRegex();
  t = $('#tip');
  x = $('#matchResult');
  tip = text = t.textContent = x.value = "";
  match = $('#text1').value.match(regex);
  if ($('#global').checked) {
    for (i = 0; i < match.length; i++) {
      text += match[i] + "\r\n";
    };
    tip = "共找到 " + match.length + " 处匹配：\r\n";
    text = text.replace(/\r\n$/, '');
  } else {
    tip = "匹配位置：" + regex.lastIndex;
    text = match[0];
  }
  t.textContent = tip;
  x.value = text;
  return true;
}
function Add1(t) {
  x = $('#replaceText');
  start = x.selectionStart;
  length = x.selectionEnd - start;
  json = x.value.split('');
  json.splice(start, length, t);
  x.value = json.join('');
  x.focus();
  x.selectionStart = t.length + start;
  x.selectionEnd = t.length + start;
}
function Replace() {
  regex = BuildRegex();
  $('#replaceResult').value = $('#text1').value.replace(regex, $('#replaceText').value);
}
function Encode() {
  t = $('#text2');
  text = t.value;
  t.value = $('#ignoreComponent').checked ? encodeURIComponent(text): encodeURI(text);
}
function Decode() {
  t = $('#text2');
  text = t.value;
  t.value = decodeURIComponent(text);
}
function EncodeHtml() {
  t = $('#text2');
  text = t.value;
  if ($('#super').checked) {
    u = "";
    for (i = 0; i < text.length; i++){
      u += "&#" + text.charCodeAt(i) + ";";
    };
  } else {
    x = $('#temp');
    x.textContent = text;
    u = x.innerHTML
    .replace(/"/g, '&quot;');
  }
  t.value = u;
}
function DecodeHtml() {
  t = $('#text2');
  text = t.value;
  x = $('#temp');
  x.innerHTML = text
  .replace(/<br>/g, '\r\n')
  .replace(/</g, '&#60;')
  .replace(/>/g, '&#62;');
  t.value = x.textContent;
}
</script>
</body>
</html>
