;function Toast(msg,duration){duration=isNaN(duration)?1000:duration;var m=document.createElement('div');m.innerText=msg;m.style.cssText="font-family:siyuan;max-width:60%;min-width: 150px;padding:0 14px;height: 40px;color: rgb(255, 255, 255);line-height: 40px;text-align: center;border-radius: 4px;position: fixed;top: 50%;left: 50%;transform: translate(-50%, -50%);z-index: 999999;background: rgba(0, 0, 0,.7);font-size: 16px;";document.body.appendChild(m);setTimeout(function(){var d=0.5;m.style.webkitTransition='-webkit-transform '+d+'s ease-in, opacity '+d+'s ease-in';m.style.opacity='0';setTimeout(function(){document.body.removeChild(m);},d*1000);},duration);}
function copy(tar) {
	let data=typeof tar=="string"?tar:tar.innerText;
	navigator.clipboard &&
	navigator.clipboard
	.writeText(data)
	.then(_=>Toast("复制成功"))
	.catch(_=>oldCopy(data)) ||
	oldCopy(data)
}
function oldCopy(str) {
    if (str != "") {
        let input = document.createElement("input");
        input.id = "copy";
        input.value = String(str);
        document.body.appendChild(input);
        input.select();
        try {
            let success = document.execCommand("copy"),
            msg = success ? "复制成功!" : "复制失败!";
            Toast(msg);
        } catch (e) {
            Toast("浏览器暂不支持复制")
        }
        document.body.removeChild(input);
    } else {
        //Toast("内容为空")
    }
}
