        /* 主按钮 - 深绿色圆形 */
        .main-btn {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background: #E9F5F3;
            color: green;
            border: none;
            cursor: pointer;
            box-shadow: 1px 1px 1px rgba(0, 0, 0, 0.5);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            outline: none;
            -webkit-tap-highlight-color: transparent;
            transition: all 0.3s ease;
            padding: 5px 2px;
            position: relative;
        }

        /* 当前页和总页数颜色区分 */
        .main-btn .current {
            color: green;
            font-weight: bold;
            margin-bottom: 2px;
        }

        .main-btn .total {
            color: rgba(0, 0, 0, 0.8);
            font-size: 0.9em;
            margin-top: 2px;
        }

        /* 分割线 */
        .main-btn .divider {
            width: 60%;
            height: 1px;
            background: green;
            margin: 3px 0;
        }

        /* 功能按钮容器 - 默认隐藏 */
        .button-group {
            display: none;
            flex-direction: column-reverse;
            align-items: center;
        }

        /* 展开时显示 */
        .expanded .button-group {
            display: flex;
        }

        /* 功能按钮样式 */
        .func-btn {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background: #495057;
            color: white;
            border: none;
            cursor: pointer;
            box-shadow: 0 2px 6px rgba(0, 0, 0, 0.7);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 18px;
            outline: none;
            margin-bottom: 8px;
        }

        /* 不同功能按钮颜色 */
        .func-btn.home { background: #9B5F64; }
        .func-btn.bottom { background: #8DA371; }
        .func-btn.top { background: #67749A; }

        /* 页码控制面板 */
        .page-control {
            background: #E9F5F3;
            color: white;
            padding: 10px;
            border-radius: 25px;
            font-size: 14px;
            box-shadow: 1px 1px 1px rgba(0, 0, 0, 0.5);
            display: flex;
            flex-direction: column;
            align-items: center;
            width: 30px;
            margin-bottom: 8px;
        }

        .page-info {
            display: flex;
            flex-direction: column;
            align-items: center;
            margin-bottom: 8px;
            font-size: 12px;
            line-height: 1.3;
            position: relative;
            width: 100%;
        }

        /* 控制面板中的分割线 */
        .page-info .divider {
            width: 90%;
            height: 1px;
            background: green;
            margin: 4px 0;
        }

        /* 控制面板中的页码颜色区分 */
        .page-info .current-page {
            color: green;
            font-weight: bold;
            font-size: 14px;
        }

        .page-info .total-pages {
            color: rgba(0, 0, 0, 0.6);
            font-size: 11px;
        }

        .page-jump {
            display: flex;
            flex-direction: column;
            align-items: center;
            width: 100%;
        }

        .page-jump input {
            width: 30px;
            padding: 6px;
            border: none;
            border-radius: 15px;
            text-align: center;
            outline: none;
            font-size: 12px;
            margin-bottom: 6px;
            background: #f8f9fa;
        }

        .page-jump button {
            width: 30px;
            height: 25px;
            background: #2b8a3e;
            color: white;
            border: none;
            border-radius: 15px;
            cursor: pointer;
            font-size: 12px;
            transition: background 0.2s;
        }

        .page-jump button:hover {
            background: #2f9e44;
        }

        /* 按钮悬停效果 */
        .main-btn:hover, .func-btn:hover {
            transform: translateY(-3px);
            box-shadow: 0 6px 12px rgba(0, 0, 0, 0.25);
        }

        /* 按钮点击效果 */
        .main-btn:active, .func-btn:active {
            transform: translateY(0);
        }

        /* 长页码时的特殊样式 */
        .long-page .main-btn {
            font-size: 11px;
            padding: 3px 1px;
        }

        .book {
            width: 100%;
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            margin-bottom: 8px;
        }
        .bookdes {
            display: flex;
            flex-direction: row;
            margin: 5px;
            width: 100%;
            position: relative;
            align-items: center;
        }
        .pic {
