// 获取基础元素
var baseUrl = window.location.href;
if(/start=\d+/.test(baseUrl) && !/page=1/.test(baseUrl)){
var title = document.querySelector('.article > h1');
title = title ? title.outerHTML : '';
var topicDoc = document.querySelector('.topic-doc');
topicDoc = topicDoc ? topicDoc.outerHTML : '';

// 获取最赞回应
var popularCommentsElements = document.querySelectorAll('#popular-comments .bg-img-green, #popular-comments .reply-quote .short, #popular-comments .comment-photos, #popular-comments .reply-content');
var popularComments = '';
for (var i = 0; i < popularCommentsElements.length; i++) {
  popularComments += popularCommentsElements[i].outerHTML;
}

// 获取普通回应
var commentsElements = document.querySelectorAll('#comments .bg-img-green, #comments .reply-quote .short, #comments .comment-photos, #comments .reply-content');
var comments = '';
for (var j = 0; j < commentsElements.length; j++) {
  comments += commentsElements[j].outerHTML;
}

// 获取分页器
var paginator = document.querySelector('.paginator');
paginator = paginator ? paginator.outerHTML : '';

// 构建新的HTML结构
var result = ''
  + '<a href="' + baseUrl + '&page=1">原文地址</a>'
  + title
  + topicDoc
  + '<br><hr><h3>最赞回应：</h3>'
  + popularComments
  + '<br><hr><h3>回应：</h3>'
  + comments
  + paginator;

// 应用内容处理规则
if(baseUrl.match(/topic/)){
  result = result
    .replace(/[\s\S]+?◎◎◎◎◎◎◎/, '')
    .replace(/style=".*?"|raw-style=".*?"/g, '')
    .replace(/<div class="cmt-img" >([\s\S]+?)<\/div>/g, '<details><summary>查看图片</summary>$1</details>')
    .replace(/<img/g, '<br><img')
    .replace(/<h3>最赞回应：<\/h3>\s*<br><hr><h3>回应：<\/h3>/, '');
} else {
  result = result.replace(/◎◎◎◎◎◎◎[\s\S]+/, '');
}

// 添加样式
var style = document.createElement('style');
style.textContent = `
.tag,a{
  color:green;
  text-decoration:none
}
img,video{
  width:100%;
  height:auto
}
summary{
  color:red
}
.short{
  color:#888;
  margin-left:5px;
  padding-left:5px;
  border-left:2px solid green;
}
h3{
  font-size:16px
}
h1{
  font-size:20px
}
.topic-card{
  background-color:#eee;
  width:100%;
  height:150px;
  border:1px solid #ddd;
}
.topic-card .group-avatar img{
  width:5%;
  float:left
}
.topic-cover img{
  width:20%;
  float:right
}
.topic-bd,.group-avatar{
  margin:0px 8px 0px 8px
}
p{
  text-indent:1.8em;
