}
.bg-img-green{
  border-top:1px solid #ddd
}
h4 .pubtime{
  font-size:13px;
  color:#666
}
`;

// 返回处理后的结果
document.documentElement.innerHTML = '<!DOCTYPE html><html><head>' + style.outerHTML + '</head><body>' + result + '</body></html>';
}

