loginUrl:
//请求头参数说明
//i=>当前选中
//ci0=>当前使用
//ci1-ci3=>历史使用
//api=>资源链接

$$$ = JSON.parse(JSON.stringify(source.getLoginHeaderMap()));
if($$$==null)$$$={};//初始化
nnn = '\n\n\n\n\n\n\n\n\n\n';
kkk = '　　　　　　　　　　';


//保存请求头
function put(json){
		return source.putLoginHeader(
			JSON.stringify(json)
		);
	}


//获取参数对应的api名称
function name(i){
		if(i==undefined)i=0;//默认接口
		return x[i]+' 【'+$$[i][0].replace(/([^\.])$/,'$1资源').replace(/\.$/,'')+'】 '
	}


//log字符串
function login(t){
		if(t==undefined)return;
		java.log(t+kkk+kkk+nnn);
		java.toast(t+kkk+kkk+nnn+nnn);
	}


//log当前接口
function look(type){
		if(type==0){
		return login('【查看当前接口】\n\n\n　　当前接口为序号'+name($$$.ci0));
		}else{
		return login('【查看历史接口】\n\n\n　　ci1:　'+name($$$.ci1)+'\n\n　　ci2:　'+name($$$.ci2)+'\n\n　　ci3:　'+name($$$.ci3)+'\n');
		}
	}


//put接口序号
function $(i){
	if(i==undefined)i=result.接口;
	if(/^ci[123]$/.test(i))eval('i=$$$.'+i);


//接口错误
if( /\D|^$/.test(i) || i<0 || i>=$$.length ){
		return login('【接口错误提示】\n\n\n　　无法获取填写的接口');
	}
else if(i==$$$.i){
		login('【取消选中提示】\n\n\n　　已取消选中');
		delete $$$.i
		return put($$$);
	}
else if(i==$$$.ci0){
		login('【无法选中提示】\n\n\n　　正在使用此接口，无需更换');
		delete $$$.i
		return put($$$);
	}

		login('【确定选择提示】\n\n\n　　确定选择序号'+name(i)+'为当前接口吗？\n\n\n　　点击上方 【确定启用接口】 按钮启用');
		$$$.i=i
		return put($$$);
}


//确定启用接口
function yes(){
		i = $$$.i
		if(i==undefined){
			return login('【接口启用提示】\n\n\n　　启用失败，没有选中接口');
			}
