<textarea rows="10" id="input" onfocus="di()" placeholder="输入菜单html源码，转化成  名称::链接   json格式"></textarea>
<button onclick="getInput();dis()" id="bt1">格式化发现</button>
<button onclick="getInput2();dis()" id="bt2">格式化发现2</button>
<button onclick="getInput3();" id="bt3">发现格式互转</button>
<button onclick="getInput4(1);" id="bt4">添加layout_flexGrow: 1</button>
